      className="relative z-30 mx-auto inline-flex min-h-12 shrink-0 items-center gap-2.5 rounded-md px-2 text-slate-100 transition-colors hover:text-white focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-sky-300 sm:min-h-14"
