import { useVegaStore } from '../../store/useVegaStore'
import { VegaEye } from './VegaEye'

const STATUS_LABEL = {
  idle: 'Monitoring. No anomalies detected.',
  alert: 'Anomaly detected.',
  investigating: 'Council investigation in progress.',
} as const

export function VegaBrand({ onRecenter }: { onRecenter: () => void }) {
  const state = useVegaStore((s) => {
    if (s.stage === 'blackout' && s.wardenDecision) return null
    if (s.councilSignal) return 'investigating'
    if (s.threatMode !== 'WATCH' || s.findings.length > 0 || s.events.some((event) => event.suspicious)) {
      return 'alert'
    }
    return 'idle'
  })

  if (!state) return null

  return (
    <>
      <span id="vega-eye-status" role="status" className="sr-only">
        {STATUS_LABEL[state]}
      </span>
      <button
        type="button"
        onClick={onRecenter}
        aria-label="VEGA — recenter topology"
        aria-describedby="vega-eye-status"
        title={`${STATUS_LABEL[state]} Click to recenter.`}
        className="vega-glass absolute top-4 left-1/2 z-30 inline-flex min-h-14 -translate-x-1/2 cursor-pointer items-center gap-3 rounded-full px-5 text-slate-100 focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-sky-300 sm:min-h-16 sm:px-6"
      >
        <VegaEye
          state={state}
          className={`h-auto w-10 shrink-0 sm:w-11 ${state === 'investigating' ? 'text-violet-300' : 'text-emerald-300'}`}
        />
        {/* Doom-inspired angular lettering traced from reference VE / GA glyphs. */}
        <svg
          aria-hidden="true"
          focusable="false"
          viewBox="0 0 148 68"
          fill="currentColor"
          className="h-10 w-auto shrink-0 sm:h-11"
        >
          <path d="M1 0H13V44L22 38V0H33V45L2 66V2Z" />
          <path d="M39 0H65L71 4V11H59V9H50V20H63V29H50V44L59 38V35H71V45L40 66V2Z" />
