    const position = id && positionsRef.current.get(id)
    if (!id || id === 'vega-core' || !position) return
    const world = toWorld(point)
    drag = {
      kind: 'node', pointerId: event.pointerId, nodeId: id, start: point,
      offset: { x: position.x - world.x, y: position.y - world.y }, moving: false,
