const onLostPointerCapture = (event: PointerEvent) => {
  if (event.target === el) endDrag(event.pointerId)
}
const onPointerLeave = (event: PointerEvent) => {
  hoverActive = false
  if (drag?.kind === 'node' && !drag.moving) endDrag(event.pointerId)
}

