arguments.command:
set -eu
work=$(mktemp -d /tmp/vega-graph-check.XXXXXX)
python3 -m http.server 4201 --bind 127.0.0.1 --directory /tmp/vega-topology.CB5h0m >"$work/http.log" 2>&1 & server=$!
google-chrome --headless --disable-gpu --no-sandbox --no-first-run --no-proxy-server --remote-debugging-port=0 --user-data-dir="$work/profile" about:blank >"$work/chrome.log" 2>&1 & chrome=$!
trap 'kill "$chrome" "$server" 2>/dev/null || true' EXIT
for i in $(seq 1 80); do if [ -s "$work/profile/DevToolsActivePort" ] && curl -fs http://127.0.0.1:4201/ >/dev/null; then break; fi; sleep .1; done
VEGA_CDP_PORT=$(head -1 "$work/profile/DevToolsActivePort") node --input-type=module <<'JS'
import assert from 'node:assert/strict'
import {writeFile} from 'node:fs/promises'
const tabs = await (await fetch(`http://127.0.0.1:${process.env.VEGA_CDP_PORT}/json/list`)).json()
const ws = new WebSocket(tabs.find(t => t.type === 'page').webSocketDebuggerUrl)
await new Promise((resolve, reject) => { ws.addEventListener('open', resolve); ws.addEventListener('error', reject) })
const pending = new Map(); let id = 0
ws.addEventListener('message', ({data}) => { const m = JSON.parse(data); const p = pending.get(m.id); if (p) {pending.delete(m.id); if (m.error) p.reject(m.error); else p.resolve(m.result)} })
const cdp = (method, params = {}) => new Promise((resolve, reject) => {pending.set(++id, {resolve,reject}); ws.send(JSON.stringify({id,method,params}))})
async function js(expression) {
  const {result,exceptionDetails} = await cdp('Runtime.evaluate',{expression,returnByValue:true})
  if (exceptionDetails) throw new Error(result.description || exceptionDetails.text)
  return result.value
}
const sleep = (ms=100) => new Promise(r=>setTimeout(r,ms))
async function wait(check) {for(let i=0;i<100;i++){if(await js(check)) return; await sleep(50)}throw new Error(`Timeout: ${check}`)}
const viewport = (width,height) => cdp('Emulation.setDeviceMetricsOverride',{width,height,deviceScaleFactor:1,mobile:false})
const mouse = (type,[x,y],extra={}) => cdp('Input.dispatchMouseEvent',{type,x,y,...extra})
const press = p => mouse('mousePressed',p,{button:'left',clickCount:1,buttons:1})
const release = p => mouse('mouseReleased',p,{button:'left',clickCount:1,buttons:0})
const move = (p,active=false) => mouse('mouseMoved',p,{buttons:active?1:0})
const point = name => js(`(() => {const r=document.querySelector('[data-node-id=${name}]').getBoundingClientRect();return [Math.round(r.x+r.width/2),Math.round(r.y+r.height/2)]})()`)
const assertNoOverlap = async () => {
  const overlaps = await js(`(() => {
    const nodes = [...document.querySelectorAll('[data-node-id]')];
    return nodes.flatMap((a,i)=>nodes.slice(i+1).flatMap(b=>{
      const x=a.getBoundingClientRect(), y=b.getBoundingClientRect();
      return x.left<y.right && x.right>y.left && x.top<y.bottom && x.bottom>y.top ? [[a.dataset.nodeId,b.dataset.nodeId]] : [];
    }));
  })()`)
