import { createServer } from 'node:http'
import { readFile } from 'node:fs/promises'
import { join } from 'node:path'
const dist = process.argv[2]
const node = (source_id, status = 'healthy', cluster = 'eng') => ({ source_id, pseudonym: source_id, role: source_id, cluster, status, heartbeat_age_sec: 1, identity_sealed: false })
const ev = (source_id, age, suspicious = false) => ({ schema_version: 1, run_id: 'fixture', event_id: `ev-${source_id}-${age}`, source_id, channel: 'file', event_time: new Date(Date.now() - age).toISOString(), ingested_at: new Date(Date.now() - age).toISOString(), payload: {}, suspicious })
const snapshot = () => ({
  threat_mode: 'WATCH', active_window_id: 'W-TEST', ttl_seconds_remaining: 180,
  nodes: [node('vega-core','healthy','core'), node('vm-online'), node('vm-stale'), node('vm-isolated','isolated')], edges: [],
  windows: [{ id: 'W-TEST', start: new Date().toISOString(), end: new Date(Date.now() + 60_000).toISOString(), status: 'collecting' }],
  events: [ev('vm-online', 59_500, true), ev('vm-stale', 121_000), ev('vm-isolated', 5_000)], findings: [], council_signal: null, oracle_assessment: null, warden_decision: null,
})
createServer(async (req, res) => {
  if (req.url === '/health') return res.writeHead(200).end('ok')
  if (req.url === '/api/state') return res.writeHead(200, { 'Content-Type': 'application/json' }).end(JSON.stringify(snapshot()))
  if (req.url === '/api/stream') {
    res.writeHead(200, { 'Content-Type': 'text/event-stream', 'Cache-Control': 'no-cache' })
    res.write(`event: snapshot\ndata: ${JSON.stringify(snapshot())}\n\n`)
    const emit = setTimeout(() => res.write(`event: event\ndata: ${JSON.stringify(ev('vm-online', 0))}\n\n`), 2300)
    const close = setTimeout(() => res.end(), 4400)
    res.on('close', () => { clearTimeout(emit); clearTimeout(close) })
    return
  }
  try {
    const path = join(dist, req.url === '/' ? 'index.html' : req.url)
    const contentType = path.endsWith('.js') ? 'text/javascript' : path.endsWith('.css') ? 'text/css' : 'text/html'
    const file = await readFile(path)
    res.writeHead(200, { 'Content-Type': contentType }).end(file)
  } catch {
    res.writeHead(404).end()
  }
}).listen(4202, '127.0.0.1')

