interface LayoutLink {
  source: string | LayoutNode
  target: string | LayoutNode
}

type CanvasDrag =
  | { kind: 'pan'; pointerId: number; last: Point }
  | { kind: 'node'; pointerId: number; nodeId: string; start: Point; offset: Point; moving: boolean }

