export type VegaEyeState = 'idle' | 'alert' | 'investigating' | 'warden'

export function useVegaEyeState(): VegaEyeState {
  return useVegaStore((state) => {
    if (state.stage === 'blackout' && state.wardenDecision) return 'warden'
