import { useEffect, useRef, useState } from 'react'
import { DashboardHeader } from './components/layout/DashboardHeader'
import { ChronosScrubber } from './components/overlays/ChronosScrubber'
import { ObserverDrawer } from './components/overlays/ObserverDrawer'
import { BlackoutOverlay } from './components/stages/BlackoutOverlay'
import { CouncilView } from './components/stages/CouncilView'
import { GhostProtocolPanel } from './components/stages/GhostProtocolPanel'
import { PanopticonCanvas, type PanopticonHandle } from './components/stages/PanopticonCanvas'
import { switchDataMode, vegaSource } from './engine/sourceManager'
import { useVegaStore } from './store/useVegaStore'

export function App() {
  const topology = useRef<PanopticonHandle>(null)
  const [headerHeight, setHeaderHeight] = useState(0)
  const threatMode = useVegaStore((s) => s.threatMode)
  const wardenDecisionId = useVegaStore((s) => s.wardenDecision?.decision_id)
  const setStage = useVegaStore((s) => s.setStage)

  useEffect(() => {
    // Open the Warden view once per decision; execution updates don't interrupt navigation.
    if (wardenDecisionId) setStage('blackout')
  }, [wardenDecisionId, setStage])

  useEffect(() => {
    // A backend restart should not leave an open dashboard stuck in replay mode.
    switchDataMode('LIVE', true)
    return () => vegaSource.stop()
  }, [])

  useEffect(() => {
    const onKeyDown = (e: KeyboardEvent) => {
      if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === 'k') {
        e.preventDefault()
        const current = useVegaStore.getState().observerOpen
        useVegaStore.getState().setObserverOpen(!current)
      } else if (e.shiftKey && e.key.toLowerCase() === 'd') {
        e.preventDefault()
        const current = useVegaStore.getState().presenterOpen
        useVegaStore.getState().setPresenterOpen(!current)
      }
    }
    window.addEventListener('keydown', onKeyDown)
    return () => window.removeEventListener('keydown', onKeyDown)
  }, [])

  return (
    <div
      data-threat-mode={threatMode}
      className="relative h-dvh w-full overflow-hidden bg-[#050811] text-slate-100"
    >
      <DashboardHeader
        onHeightChange={setHeaderHeight}
        onRecenter={() => {
          topology.current?.recenter()
          setStage('panopticon')
        }}
      />

      <main className="relative h-full overflow-clip">
        <PanopticonCanvas ref={topology} />
        <GhostProtocolPanel headerHeight={headerHeight} />
        <CouncilView />
        <BlackoutOverlay />
      </main>

      <ChronosScrubber />
      <ObserverDrawer />
    </div>
  )
}

export default App
import {
  ArrowRight,
  FastForward,
  Pause,
  Play,
  PlusCircle,
  Radio,
  RotateCcw,
  ShieldCheck,
  Zap,
} from 'lucide-react'
import { AnimatePresence, motion } from 'motion/react'
import { flushLiveWindow, switchDataMode, vegaSource } from '../../engine/sourceManager'
import { useVegaStore } from '../../store/useVegaStore'

export function PresenterBar() {
  const presenterOpen = useVegaStore((s) => s.presenterOpen)
  const dataMode = useVegaStore((s) => s.dataMode)
  const isPlaying = useVegaStore((s) => s.isPlaying)
  const scenarioId = useVegaStore((s) => s.scenarioId)
  const stage = useVegaStore((s) => s.stage)
  const hasFindings = useVegaStore((s) => s.findings.length > 0)
  const chronosExpanded = useVegaStore((s) => s.chronosExpanded)
  const wardenDecision = useVegaStore((s) => s.wardenDecision)

  const nextCueLabel =
    stage === 'panopticon'
      ? hasFindings
        ? 'Next: Inspect Node'
        : dataMode === 'LIVE'
          ? 'Next: Flush Window'
          : 'Next: Inject Anomaly'
      : stage === 'ghost_protocol'
        ? 'Next: The Council'
        : stage === 'council'
          ? chronosExpanded
            ? 'Next: Blackout'
            : 'Next: Chronos'
          : stage === 'blackout'
            ? wardenDecision?.execution_status === 'awaiting_authorization'
              ? 'Next: Authorize'
              : 'Next: Observer'
            : 'Next Cue'

  return (
    <AnimatePresence>
      {presenterOpen && (
        <motion.div
          initial={{ opacity: 0, y: -10 }}
          animate={{ opacity: 1, y: 0 }}
          exit={{ opacity: 0, y: -10 }}
          transition={{ duration: 0.18 }}
          className="vega-panel pointer-events-auto absolute inset-x-4 top-full mt-2 ml-auto flex w-fit flex-wrap items-center gap-2 rounded-xl px-3 py-2 text-xs"
        >
          {/* Source Mode Toggle */}
          <div className="flex items-center gap-1 rounded-md border border-slate-800 bg-slate-950 p-0.5 font-mono-tabular text-[10px]">
            <button
              type="button"
              onClick={() => switchDataMode('SIMULATED')}
              className={`rounded px-2 py-0.5 transition ${
                dataMode === 'SIMULATED'
                  ? 'bg-amber-500/20 text-amber-200'
                  : 'text-slate-400 hover:text-slate-200'
              }`}
            >
              SIMULATED
            </button>
            <button
              type="button"
              onClick={() => switchDataMode('LIVE')}
              className={`inline-flex items-center gap-1 rounded px-2 py-0.5 transition ${
                dataMode === 'LIVE'
                  ? 'bg-emerald-500/20 text-emerald-200'
                  : 'text-slate-400 hover:text-slate-200'
              }`}
            >
              <Radio className="h-2.5 w-2.5" />
              LIVE
            </button>
          </div>

          <div className="h-4 w-px bg-slate-800" />

          <button
            type="button"
            onClick={() => vegaSource.advanceCue()}
            className="inline-flex items-center gap-1.5 rounded-md border border-sky-400/60 bg-sky-500/20 px-2.5 py-1 font-semibold text-sky-100 hover:bg-sky-500/30"
          >
            <span>{nextCueLabel}</span>
            <ArrowRight className="h-3 w-3" />
          </button>

          {dataMode === 'SIMULATED' && (
            <>
              <button
                type="button"
                onClick={() => vegaSource.stepNextEvent()}
                className="inline-flex items-center gap-1 rounded-md border border-slate-700 bg-slate-900 px-2 py-1 text-slate-200 hover:border-sky-400/50"
                title="Emit one single event without changing stage"
              >
                <PlusCircle className="h-3 w-3 text-sky-400" />
                <span>+1 Event</span>
              </button>

              <button
                type="button"
                onClick={() => vegaSource.injectAnomaly()}
                className="inline-flex items-center gap-1 rounded-md border border-red-500/40 bg-red-500/15 px-2.5 py-1 font-medium text-red-200 hover:bg-red-500/25"
              >
                <Zap className="h-3 w-3" />
                <span>Inject Anomaly</span>
              </button>
            </>
          )}

