import assert from 'node:assert/strict'
import {drawTopologyDots} from './frontend/src/engine/drawTopologyDots.ts'
const quiet={x:0,y:0,strength:0,motion:0}
class Path {
  points = []
  moveTo() {}
  arc(x,y,r) { this.points.push({x,y,r}) }
}
globalThis.Path2D=Path
function draw(w,h,p,z,hover=quiet) {
  const points=[]
  const ctx={save(){},restore(){},beginPath(){this.current=new Path()},moveTo(){},arc(...args){this.current.arc(...args)},stroke(path=this.current){points.push(...path.points)}}
  drawTopologyDots(ctx,w,h,p,z,hover)
  return points
}
for(const [w,h,p,z] of [[1440,900,{x:720,y:450},1],[390,844,{x:120,y:300},.5],[2500,1100,{x:-2250,y:544},1.42],[800,480,{x:12345,y:-5678},.8],[700,500,{x:390,y:421},.6]]) {
  const actual=draw(w,h,p,z)
  const expected=[]
  for(let k=0; ;k++) {
    const radius=130+100*k
    if (radius*z>Math.hypot(w,h)+Math.hypot(p.x,p.y)+100) break
    const count=Math.round(2*Math.PI*radius/54)
